  function route(){const hash=location.hash||('#'+location.pathname.replace(/^\//,''));let match;try{if((match=/^#servers\/([^/]+)(?:\/channels\/([^/]+))?$/.exec(hash)))return {view:'servers',communityId:decodeURIComponent(match[1]),channelId:match[2]?decodeURIComponent(match[2]):null};}catch(_){return {view:'chats'};}return {view:['#chats','#servers','#you'].includes(hash)?hash.slice(1):'chats'};}
