  function secureDraft(){const id=state.secureRoomId;if(!id)return null;if(!state.secureDrafts.has(id))state.secureDrafts.set(id,{text:'',pending:null,busy:false,error:''});return state.secureDrafts.get(id);}
  function captureSecureDraft(){const input=$('home-secure-input'),id=renderedContext?.accountId===state.account?.id?renderedContext.roomId:state.secureRoomId,draft=id?state.secureDrafts.get(id):null;if(input&&draft)draft.text=input.value;}
