  function secureConversation(){const room=state.secureRooms.find(r=>r.id===state.secureRoomId),draft=secureDraft();return `<header class="vh-page-header vh-conversation-header"><button class="vh-icon-button vh-mobile-back" data-home="secure-back" aria-label="Back to chats">${icon('back')}</button><div><span class="vh-eyebrow">ENCRYPTED CHAT</span><h1>${esc(room?.name||'Conversation')}</h1></div><button class="vh-icon-button" data-home="secure-verify" aria-label="Verify messaging devices">${icon('shield')}</button></header><div id="home-secure-feed" class="vh-feed" tabindex="0" aria-label="Encrypted conversation history">${secureFeedHTML()}</div><form data-home-form="secure-message" class="vh-secure-composer"><label class="vh-sr-only" for="home-secure-input">Encrypted message</label><textarea id="home-secure-input" rows="2" maxlength="4000" placeholder="Write a message…">${esc(draft.text)}</textarea><button class="vh-primary" type="submit" ${draft.busy?'disabled':''}>${draft.busy?'Sending…':icon('arrow')}<span class="vh-sr-only">Send encrypted message</span></button></form><div class="vh-compose-status"><span id="home-secure-status" role="status">${esc(draft.error||'Verify recipient devices before sending. Drafts stay in memory while this tab is open.')}</span><button class="vh-text-button" data-home="secure-retry" id="home-secure-retry" ${draft.pending&&!draft.busy?'':'hidden'}>Retry unconfirmed message</button><button class="vh-text-button" data-home="secure-verify">Verify keys</button></div>`;}
