  async function sendSecure(retry=false){const initiating={accountId:state.account?.id,messenger:state.secure,roomId:state.secureRoomId};if(!await checkSession())return;if(state.account?.id!==initiating.accountId||state.secure!==initiating.messenger||state.secureRoomId!==initiating.roomId)return;if(!secureReady()||!state.secureRoomId)return announce('Connect and verify a messaging device before sending.');captureSecureDraft();const messenger=state.secure,id=state.secureRoomId,account=state.account?.id,draft=secureDraft(),text=retry&&draft.pending?draft.pending.text:draft.text.trim();if(!text||draft.busy)return;if(text.length>4000)return announce('Use at most 4,000 characters.');if(draft.pending&&draft.pending.text!==text){draft.error='An earlier message is still unconfirmed. Retry it using the button below; your newer draft will stay here.';updateSecureComposer();return;}if(!draft.pending)draft.pending={text,clientId:crypto.randomUUID()};const pending=draft.pending;draft.busy=true;draft.error='Sending encrypted message…';updateSecureComposer();try{await messenger.sendText(id,pending.text,{clientId:pending.clientId});if(state.secure!==messenger||state.account?.id!==account)return;draft.pending=null;draft.error='Saved by the messaging server. This does not confirm delivery to another device.';if(draft.text.trim()===pending.text)draft.text='';if(id===state.secureRoomId){const input=$('home-secure-input');if(input&&input.value.trim()===pending.text)input.value='';await refreshSecureMessages();input?.focus();}}catch(error){if(state.secure===messenger&&state.account?.id===account){draft.error=error.message+' Your text is still here; retry uses the same message ID.';}}finally{draft.busy=false;if(state.secure===messenger&&id===state.secureRoomId)updateSecureComposer();}}
  function updateSecureComposer(){const draft=secureDraft(),status=$('home-secure-status'),form=document.querySelector('[data-home-form="secure-message"]');if(status&&draft)status.textContent=draft.error||'Verify recipient devices before sending.';const retry=$('home-secure-retry');if(retry&&draft)retry.hidden=!draft.pending||draft.busy;const button=form?.querySelector('[type="submit"]');if(button&&draft){button.disabled=draft.busy;button.setAttribute('aria-busy',String(draft.busy));}}
  async function secureOlder(button){const messenger=state.secure,id=state.secureRoomId,current=guard(),feed=$('home-secure-feed'),top=feed?.scrollTop||0,height=feed?.scrollHeight||0;if(!messenger||!id)return;try{if(button)button.disabled=true;const messages=await messenger.older(id);if(!current()||state.secure!==messenger)return;state.secureMessages=messages;renderSecureFeed();const next=$('home-secure-feed');if(next)next.scrollTop=top+next.scrollHeight-height;}catch(error){if(current())announce(error.message);}finally{if(button?.isConnected)button.disabled=false;}}
  function newSecureRoom(){if(!secureReady())return secureConnect();showDialog('A private conversation.','Choose exact Matrix identities. New rooms use encryption; no one is added automatically.',`<form class="vh-form" data-home-form="secure-create"><label class="vh-field">Conversation title <span>Optional for a direct message</span><input name="name" maxlength="80"></label><label class="vh-field">Participants<span>Exact @name:server identities, one per line. Up to 8 people including you.</span><textarea name="invites" rows="3" placeholder="@friend:example.org" required autofocus></textarea></label><label class="vh-check"><input type="checkbox" name="isDirect" checked>Direct message (one recipient)</label>${formError}<button class="vh-primary" type="submit">Create encrypted conversation</button></form>`);}
  async function createSecureRoom(form,data){const current=guard(),messenger=state.secure;if(!messenger||!secureReady())throw Error('Connect messaging first.');const invites=[...new Set(String(data.invites||'').split(/[\s,]+/).filter(Boolean))];if(!invites.length||invites.length>7||invites.some(id=>!/^@[^:\s]+:[^\s]+$/.test(id)))throw Error('Enter 1–7 exact Matrix identities, such as @friend:example.org.');const direct=data.isDirect==='on';if(direct&&invites.length!==1)throw Error('A direct message has exactly one recipient. Uncheck direct message for a group.');const result=await messenger.createRoom({name:String(data.name||'').trim(),invites,isDirect:direct});if(!current()||messenger!==state.secure)return;closeDialog();await refreshSecureRooms();if(!current())return;const id=typeof result==='string'?result:result.roomId||result.room_id||result.id;if(id)await openSecureRoom(id);}
  async function secureFingerprint(){const current=guard(),messenger=state.secure;if(!messenger)return secureConnect();const fingerprint=await messenger.fingerprint();if(!current()||messenger!==state.secure)return;showDialog('This messaging device.','Compare this public identity fingerprint over a channel you trust. It is not a recovery secret.',`<div class="vh-note"><b>${esc(fingerprint.userId)}</b><p>Device ${esc(fingerprint.deviceId)}</p><p class="vh-fingerprint">${esc(fingerprint.ed25519)}</p></div><button class="vh-secondary" data-home="secure-verify">Verify another device</button>`);}
  async function secureDevices(userId){const current=guard(),messenger=state.secure;if(!messenger)return secureConnect();const ticket=showDialog('Verify messaging identities.','Signing in does not verify messaging devices. Compare a device fingerprint with its owner before marking it verified.',`<form class="vh-form" data-home-form="secure-device-search"><label class="vh-field">Exact messaging identity<input name="userId" value="${esc(typeof userId==='string'?userId:'')}" placeholder="@friend:example.org" required></label><button class="vh-secondary" type="submit">Find this identity’s devices</button></form><div id="home-secure-devices" role="status">Loading messaging devices…</div>${formError}`);try{const devices=await messenger.devices(typeof userId==='string'?userId:undefined);if(!current()||ticket!==state.dialogGeneration||messenger!==state.secure)return;const n=$('home-secure-devices');if(n)n.innerHTML=devices.map(d=>`<article class="vh-list-row"><div><b>${esc(d.userId)}</b><p>${esc(d.name||d.deviceId)}${d.current?' · this device':''}</p><small>${d.verified?'Verified':'Not verified'}</small></div>${d.verified?'':`<button class="vh-secondary" data-verify-user="${esc(d.userId)}" data-verify-device="${esc(d.deviceId)}">Compare</button>`}</article>`).join('')+'<button class="vh-secondary" data-home="secure-fingerprint">View this device fingerprint</button>';}catch(error){if(current()&&ticket===state.dialogGeneration)errorNode(error);}}
  function compareDevice(userId,deviceId){showDialog('Compare the public fingerprint.','Ask the person to show their device’s Ed25519 fingerprint using a trusted channel. Paste the exact value only after comparison.',`<form class="vh-form" data-home-form="secure-fingerprint"><input type="hidden" name="userId" value="${esc(userId)}"><input type="hidden" name="deviceId" value="${esc(deviceId)}"><label class="vh-field">Expected fingerprint<input name="fingerprint" required autocomplete="off" spellcheck="false" autofocus></label><p>${esc(userId)} / ${esc(deviceId)}</p>${formError}<button class="vh-primary" type="submit">Verify exact fingerprint</button></form>`);}
